580: def desktop_app_server_started_at(now: float | None = None) -> float | None:
581:     """Return the current Windows Codex app-server process epoch, cached.
582: 
583:     This is used only as a freshness fence for rollout fallback. Failure to
584:     inspect processes degrades to the previous behavior; it never changes
585:     lifecycle state or stops a process.
586:     """
587:     now = time.time() if now is None else now
588:     if now - float(_desktop_epoch_cache.get("checked_at", 0.0) or 0.0) < 10.0:
589:         return _desktop_epoch_cache.get("value")
590:     value = None
591:     if psutil is not None and os.name == "nt":
592:         try:
593:             for proc in psutil.process_iter(["name", "cmdline", "create_time"]):
594:                 name = str(proc.info.get("name") or "").casefold()
595:                 command = " ".join(proc.info.get("cmdline") or [])
596:                 if name == "codex.exe" and "app-server" in command:
597:                     created = float(proc.info.get("create_time") or 0.0)
598:                     value = max(value or 0.0, created)
599:         except (psutil.Error, OSError, ValueError, TypeError):
600:             value = None
601:     _desktop_epoch_cache.update(checked_at=now, value=value)
602:     return value
